use vstd::prelude::*;

verus! {

    // Mathematical prefix sum S(k) = sum_{i=1..k} a[i], where
    // a[i] = -i if i odd, +i if i even.
    // Closed‐form:
    //   S(k) =  k/2      if k even
    //           −(k+1)/2  if k odd
    spec fn S(k: int) -> int
        requires
            k >= 0,
        decreases
            k,
    {
        if k % 2 == 0 {
            k / 2
        } else {
            -(k + 1) / 2
        }
    }

    // Executable implementation of the above prefix sum for an i8 argument k >= 0.
    // We widen to i16 to avoid overflow on (k+1) when k = 127.
    fn prefix_sum(k: i8) -> i8
        requires
            to_int(k) >= 0,
        ensures
            to_int(prefix_sum(k)) == S(to_int(k)),
    {
        let k16: i16 = k as i16;
        let r16: i16 = if k16 % 2 == 0 {
            k16 / 2
        } else {
            // k16 <= 127, so k16 + 1 <= 128 fits in i16
            -(k16 + 1) / 2
        };
        // r16 is in [−64, 63], hence safe to cast back to i8
        assert(r16 >= -128 && r16 <= 127);
        r16 as i8
    }

    // Solve the list of queries: each query is (l, r) with 1 ≤ l ≤ r.
    // We return for each query the exact sum S(r) − S(l−1), cast back to i8.
    fn solve(queries: Vec<(i8, i8)>) -> Vec<i8>
        requires
            // Problem precondition: each query satisfies 1 ≤ l ≤ r
            forall |i: nat|
                i < queries.len() ==>
                let (l, r) = queries.index(i);
                1 <= to_int(l) && to_int(l) <= to_int(r),
        ensures
            // Output length matches and each entry equals the mathematical sum
            ret.len() == queries.len() &&
            forall |i: nat|
                i < ret.len() ==>
                let (l, r) = queries.index(i);
                to_int(ret.index(i)) == S(to_int(r)) - S(to_int(l) - 1),
    {
        let mut res: Vec<i8> = Vec::new();
        res.reserve(queries.len());

        let mut idx: nat = 0;
        while idx < queries.len()
            invariant
                idx <= queries.len(),
                res.len() == idx,
                // invariant: for all processed j < idx we have already got the correct sum
                forall |j: nat|
                    j < idx ==>
                    let (lj, rj) = queries.index(j);
                    to_int(res.index(j)) == S(to_int(rj)) - S(to_int(lj) - 1),
            decreases
                queries.len() - idx,
        {
            let (l, r): (i8, i8) = queries.index(idx);
            // l ≥ 1 by requires, so l−1 ≥ 0
            let l1: i8 = l - 1;

            // compute prefix sums
            let spr: i8 = prefix_sum(r);
            let spl1: i8 = prefix_sum(l1);

            // do the subtraction in mathematical int to avoid any i8 overflow,
            // then cast back to i8 after checking bounds
            let diff_int: int = to_int(spr) - to_int(spl1);
            assert(diff_int >= -128 && diff_int <= 127);
            let ans: i8 = diff_int as i8;

            res.push(ans);
            idx = idx + 1;
        }

        res
    }

}

